<template>
  <section id="content-workspace" class="content-workspace" aria-labelledby="content-title">
    <header class="content-workspace-header"><div><p class="records-eyebrow">FIND / COLLECT / CREATE</p><h2 id="content-title">内容工作台</h2><p>在已保存的内容里找到一句话，把来源留下，再围绕用途组织表达。</p></div><span class="local-note">本地检索 · 主动收藏 · 来源可追溯</span></header>
    <nav class="content-tabs" aria-label="内容工作台"><button v-for="item in tabs" :key="item.id" type="button" :class="{ active: tab === item.id }" @click="changeTab(item.id)">{{ item.label }}</button></nav>

    <div v-show="tab === 'search'" class="workspace-pane">
      <form class="content-search-form" @submit.prevent="search(true)"><label class="search-main-label"><span>搜索视频内容</span><input v-model="query.q" placeholder="输入关键词，多个词同时匹配；引号内连续短语" type="search" /></label><el-button native-type="submit" type="primary" :loading="busy">全文搜索</el-button></form>
      <p class="workspace-help">搜索标题、作者、原始转写、整理稿与 AI 总结，也包括独立蒸馏保存的逐视频资料；不会调用模型。多词可跨同一视频的不同内容命中。</p>
      <div class="content-filters"><label>作者<select v-model="query.author" @change="search(true)"><option value="">全部作者</option><option v-for="author in searchAuthors" :key="author">{{ author }}</option></select></label><label>内容范围<select v-model="query.type" @change="search(true)"><option value="">全部逐视频内容</option><option value="original">原始转写</option><option value="polished">整理稿</option><option value="summary">AI 总结</option><option value="distill">独立博主蒸馏结果</option></select></label><label>排序<select v-model="query.sort" @change="search(true)"><option value="relevance">相关度</option><option value="time">最近采集</option></select></label><label>采集日期起<input v-model="query.from" type="date" @change="search(true)" /></label><label>至<input v-model="query.to" type="date" @change="search(true)" /></label></div>
      <el-alert v-if="error" :title="error" type="error" :closable="false" />
      <div v-if="searched" class="search-result-toolbar"><div class="result-count" role="status">找到 {{ searchTotal }} {{ query.type === 'distill' ? '份博主蒸馏结果，跨视频归纳单独展示' : '个视频，按视频聚合' }}；每段都标明文本来源。</div><div class="search-result-actions"><el-button size="small" :aria-expanded="!resultsCollapsed" aria-controls="content-search-results" @click="toggleResults">{{ resultsCollapsed ? '展开搜索结果' : '收起搜索结果' }}</el-button><el-button size="small" @click="clearSearch">清空搜索</el-button><el-button size="small" type="primary" plain @click="returnToTasks">返回任务看板</el-button></div></div>
      <div v-show="!resultsCollapsed" id="content-search-results" ref="resultsViewport" class="search-results" role="region" aria-label="搜索结果，独立滚动" tabindex="0">
        <article v-for="result in searchResults" :key="result.aweme_id" class="content-result">
          <div class="content-result-cover"><img v-if="result.cover" :src="result.cover" alt="视频封面" loading="lazy" /><span v-else>VIDEO</span></div>
          <div class="content-result-body"><header><span>{{ result.author || '未知作者' }}</span><small>{{ dateText(result.collected_at) }} · 采集时间</small></header><h3>{{ result.title || '未命名视频' }}</h3>
            <div v-for="(match, index) in result.matches" :key="`${match.source_id}-${index}`" class="search-match"><span class="source-badge">{{ sourceLabel(match.source_type) }}<template v-if="match.time_seconds != null"> · {{ timeLabel(match.time_seconds) }}</template></span><button type="button" class="match-text" @click="readMatch(result, match)"><span v-for="(part, partIndex) in snippet(match)" :key="partIndex"><mark v-if="part.hit">{{ part.text }}</mark><template v-else>{{ part.text }}</template></span></button></div>
            <footer><el-button size="small" @click="openContentReader({ aweme_id: result.aweme_id })">{{ query.type === 'distill' ? '打开蒸馏全文' : '打开全文与视频' }}</el-button><el-button size="small" @click="addToTopic({ aweme_id: result.aweme_id })">加入专题</el-button></footer>
          </div>
        </article>
      </div>
      <el-empty v-if="searched && !resultsCollapsed && !busy && !searchResults.length" description="没有匹配内容，可以换一个词或放宽筛选" />
      <div v-if="!searched" class="content-welcome"><span>01</span><h3>从一句话找回一段视频。</h3><p>标题里没有的观点，也能从口播和总结中找出来。搜索与任务列表筛选各自独立。</p></div>
      <el-pagination v-if="!resultsCollapsed && searchTotal > 20" :current-page="query.page" :total="searchTotal" :page-size="20" layout="prev,pager,next,total" @current-change="(page: number) => { query.page = page; search(false) }" />
    </div>

    <div v-show="tab === 'materials'" class="workspace-pane">
      <div class="materials-toolbar"><label class="search-main-label"><span>搜索句子素材</span><input v-model="materialQuery.q" type="search" placeholder="摘录、标签、备注或个人改写" @keyup.enter="loadMaterials" /></label><el-button @click="loadMaterials">搜索</el-button><el-button type="primary" @click="newNote">新建个人笔记</el-button></div>
      <div class="content-filters"><label>作者<select v-model="materialQuery.author" @change="loadMaterials"><option value="">全部作者</option><option v-for="author in materialAuthors" :key="author">{{ author }}</option></select></label><label>标签<select v-model="materialQuery.tag" @change="loadMaterials"><option value="">全部标签</option><option v-for="tag in materialTags" :key="tag">{{ tag }}</option></select></label><label>来源类型<select v-model="materialQuery.source_type" @change="loadMaterials"><option value="">全部类型</option><option value="original">原始转写</option><option value="polished">整理稿</option><option value="summary">AI 总结</option><option value="note">个人笔记</option></select></label><span>删除下载记录或视频，不会删除已收藏的来源快照。</span></div>
      <div class="material-grid">
        <article v-for="material in materials" :key="material.id" class="material-card"><header><span>{{ sourceLabel(material.source_type) }}</span><small>{{ material.author || '我的笔记' }}</small></header><h3>{{ material.title }}</h3><blockquote>{{ material.excerpt || material.text }}</blockquote><p v-if="material.source_missing" class="source-state">来源已删除，收藏快照仍保留</p><p v-else-if="material.source_updated" class="source-state">来源已更新，此处保留收藏时快照</p><div v-if="material.tags?.length" class="material-tags"><span v-for="tag in material.tags" :key="tag">#{{ tag }}</span></div><p v-if="material.notes" class="material-annotation"><strong>我的理解</strong>{{ material.notes }}</p><p v-if="material.rewrite" class="material-annotation"><strong>个人改写</strong>{{ material.rewrite }}</p><footer><el-button v-if="material.source_id || material.aweme_id" size="small" @click="openContentReader({ source_id: material.source_id, revision: material.revision, aweme_id: material.aweme_id })">返回来源</el-button><el-button size="small" @click="addToTopic({ material_id: material.id })">加入专题</el-button><el-button size="small" @click="editMaterial(material)">编辑</el-button><el-button size="small" @click="removeMaterial(material)">删除素材</el-button></footer></article>
      </div><el-empty v-if="!materials.length && !busy" description="尚无素材，阅读口播或总结时选中文字即可收藏" />
    </div>

    <div v-show="tab === 'topics'" class="workspace-pane">
      <div class="topic-layout"><aside class="topic-sidebar"><el-button type="primary" @click="createTopic">新建专题</el-button><button v-for="item in topics" :key="item.id" type="button" :class="{ active: topic?.id === item.id }" @click="selectTopic(item.id)"><strong>{{ item.name }}</strong><span>{{ item.goal || '尚未填写用途' }}</span></button><p v-if="!topics.length" class="workspace-help">创建一个专题，将视频资料、句子和笔记放在一起。</p></aside>
        <div v-if="topic" class="topic-detail"><header class="topic-heading"><div><span class="source-badge">专题 / 用途组织</span><h3>{{ topic.name }}</h3><p>{{ topic.goal || '点击编辑，说明这个专题准备做什么。' }}</p><p v-if="topic.description">{{ topic.description }}</p></div><div><el-button size="small" @click="editTopic">编辑专题</el-button><el-button size="small" @click="exportTopic()">导出资料</el-button><el-button size="small" @click="deleteTopic">删除专题</el-button></div></header>
          <div class="topic-members-heading"><h4>资料范围 <small>{{ selectedMembers.length }}/{{ topic.members?.length || 0 }} 已选择</small></h4><div><el-button size="small" @click="selectAllMembers">全选 / 清空</el-button><el-button size="small" @click="addTopicNote">添加个人笔记</el-button></div></div>
          <div class="topic-members"><article v-for="(member, index) in topic.members || []" :key="member.id" class="topic-member"><input v-model="selectedMembers" type="checkbox" :value="member.id" :aria-label="`选择资料 ${member.title}`" /><div><span class="source-badge">{{ sourceLabel(member.source_type || 'note') }}<template v-if="member.group_name"> / {{ member.group_name }}</template></span><h5>{{ member.title || '未命名资料' }}</h5><p>{{ member.text || '视频引用：请选择已有口播或总结加入后再参与生成，不会自动分析媒体。' }}</p><p v-if="member.notes" class="member-note">专题备注：{{ member.notes }}</p><div class="member-actions"><el-button v-if="member.source_id || member.aweme_id" size="small" @click="openContentReader({ source_id: member.source_id, revision: member.revision, aweme_id: member.aweme_id })">返回来源</el-button><el-button size="small" @click="editMember(member)">分组 / 备注</el-button><el-button size="small" :disabled="index === 0" @click="moveMember(index, -1)">上移</el-button><el-button size="small" :disabled="index === (topic.members?.length || 0) - 1" @click="moveMember(index, 1)">下移</el-button><el-button size="small" @click="removeMember(member)">移出专题</el-button></div></div></article></div>
          <el-empty v-if="!topic.members?.length" description="从搜索、来源阅读或素材库点击“加入专题”" />
          <div class="topic-generation"><h4>基于选中资料生成</h4><p class="workspace-help">只发送本次勾选的资料和下面的要求。归纳保留来源编号，创作内容单独标明；不默认补充外部知识。</p><div class="generation-settings"><label>操作<select v-model="generation.action"><option value="points">整理素材要点</option><option value="structure">提炼表达结构</option><option value="angles">几个写作角度</option><option value="outline">生成提纲</option><option value="draft">生成初稿</option></select></label><label>用途<input v-model="generation.settings.purpose" /></label><label>受众<input v-model="generation.settings.audience" /></label><label>语气<input v-model="generation.settings.tone" /></label><label>篇幅<input v-model="generation.settings.length" placeholder="例如 800 字" /></label><label>本专题累计请求上限<input v-model.number="generation.request_limit" type="number" min="1" placeholder="留空不限次数" /></label></div><el-button type="primary" :disabled="!selectedMembers.length" :loading="busy" @click="previewGeneration">预览将发送的资料</el-button></div>
          <section v-if="topic.versions?.length" class="topic-versions"><h4>生成版本</h4><article v-for="version in topic.versions" :key="version.id" class="topic-version"><header><strong>{{ actionLabels[version.action || ''] || '生成结果' }} · {{ dateText(version.created_at) }}</strong><span>{{ versionLabels[version.status] || version.status }}</span></header><p v-if="version.error" class="source-state">{{ version.error }}</p><p v-for="warning in version.warnings || []" :key="warning" class="source-state">{{ warning }}</p><pre>{{ version.edited_markdown || version.output_markdown || (['queued', 'running'].includes(version.status) ? '正在生成，结果会独立保存。' : '当前没有可用正文，采用的资料快照仍保留。') }}</pre><details><summary>查看当次采用的资料快照（{{ version.inputs?.length || 0 }} 条）</summary><article v-for="input in version.inputs || []" :key="input.citation_id" class="version-input"><strong>[{{ input.citation_id }}] {{ input.title }}</strong><small>{{ sourceLabel(input.source_type) }}</small><p>{{ input.text }}</p><el-button v-if="input.source_id || input.aweme_id" size="small" @click="openContentReader({ source_id: input.source_id, revision: input.revision, aweme_id: input.aweme_id })">核对来源</el-button></article></details><footer><el-button v-if="version.status === 'paused'" size="small" type="primary" :loading="busy" @click="resumeTopic">调整上限并继续此版本</el-button><el-button size="small" :disabled="!version.output_markdown" @click="editVersion(version)">编辑独立稿</el-button><el-button size="small" @click="exportTopic(version.id)">导出此版本</el-button></footer></article></section>
        </div><div v-else class="topic-empty"><span>03</span><h3>先明确用途，再组织资料。</h3><p>专题跨作者、跨视频整理素材，不会重新下载或重新分析所有视频。</p></div>
      </div>
    </div>

    <el-dialog v-model="materialEditVisible" :title="editingMaterial ? '编辑素材' : '新建个人笔记'" width="min(620px, 94vw)"><p v-if="editingMaterial" class="workspace-help">来源摘录固定保存；修改只影响标题、标签、理解和独立改写。</p><label class="workspace-field">标题<input v-model="materialForm.title" /></label><label v-if="!editingMaterial" class="workspace-field">个人笔记<textarea v-model="materialForm.text" rows="6" /></label><blockquote v-else class="edit-snapshot">{{ editingMaterial.excerpt || editingMaterial.text }}</blockquote><label class="workspace-field">标签（逗号分隔）<input v-model="materialForm.tags" /></label><label class="workspace-field">个人备注<textarea v-model="materialForm.notes" rows="3" /></label><label class="workspace-field">个人改写<textarea v-model="materialForm.rewrite" rows="3" /></label><template #footer><el-button @click="materialEditVisible = false">取消</el-button><el-button type="primary" :loading="busy" @click="saveMaterial">保存</el-button></template></el-dialog>
    <el-dialog v-model="topicEditVisible" title="专题设置" width="min(540px, 94vw)"><label class="workspace-field">名称<input v-model="topicForm.name" /></label><label class="workspace-field">目标 / 用途<input v-model="topicForm.goal" /></label><label class="workspace-field">说明<textarea v-model="topicForm.description" rows="4" /></label><template #footer><el-button @click="topicEditVisible = false">取消</el-button><el-button type="primary" :loading="busy" @click="saveTopic">保存</el-button></template></el-dialog>
    <el-dialog v-model="previewVisible" title="确认本次模型资料范围" width="min(780px, 94vw)"><el-alert title="下面列出的文字将发送至已配置的模型服务" description="只包含勾选资料的快照和生成要求，不发送整座素材库，不重新下载或分析视频。可能产生费用；本专题累计次数包括之前的生成、重试与备用通道，不按版本重置。" type="warning" :closable="false" /><p>{{ preview?.characters || 0 }} 字 · {{ preview?.inputs?.length || 0 }} 条资料 · {{ actionLabels[generation.action] }}</p><div class="preview-inputs"><article v-for="input in preview?.inputs || []" :key="input.citation_id"><strong>[{{ input.citation_id }}] {{ input.title }}</strong><small>{{ sourceLabel(input.source_type) }}</small><pre>{{ input.text }}</pre></article></div><template #footer><el-button @click="previewVisible = false">返回调整</el-button><el-button type="primary" :loading="busy" @click="generate">确认生成新版本</el-button></template></el-dialog>
    <el-dialog v-model="versionEditVisible" title="编辑独立稿" width="min(860px, 94vw)"><p class="workspace-help">编辑稿与模型原始结果分别保留；重新生成将创建新版本，不覆盖此稿。</p><textarea v-model="versionDraft" class="version-editor" rows="20" /><template #footer><el-button @click="versionEditVisible = false">取消</el-button><el-button type="primary" :loading="busy" @click="saveVersion">保存编辑稿</el-button></template></el-dialog>
  </section>
</template>

<script setup lang="ts">
import { ref, reactive, onMounted, onBeforeUnmount, nextTick } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { contentApi, sourceLabel, openContentReader, addToTopic, type ContentVideo, type ContentSource, type Material, type Topic, type TopicMember, type TopicVersion } from '@/api/content'
import { textParts, timeLabel } from '@/utils/contentText'
const tabs = [{ id: 'search', label: '全文搜索' }, { id: 'materials', label: '句子素材库' }, { id: 'topics', label: '专题工作台' }]
const stateKey = 'dl-content-workspace-state-v1'
let initial: any = {}; try { initial = JSON.parse(sessionStorage.getItem(stateKey) || '{}') } catch { /* 忽略损坏的本地界面状态。 */ }
const tab = ref(initial.tab || 'search'), busy = ref(false), error = ref(''), searched = ref(false)
const query = reactive({ q: initial.q || '', author: initial.author || '', type: initial.type || '', sort: initial.sort || 'relevance', page: initial.page || 1, from: initial.from || '', to: initial.to || '' })
const searchResults = ref<ContentVideo[]>([]), searchTotal = ref(0), searchAuthors = ref<string[]>([])
const resultsCollapsed = ref(Boolean(initial.resultsCollapsed)), resultsViewport = ref<HTMLElement | null>(null)
const materials = ref<Material[]>([]), materialAuthors = ref<string[]>([]), materialTags = ref<string[]>([]), materialQuery = reactive({ q: '', author: '', tag: '', source_type: '' })
const materialEditVisible = ref(false), editingMaterial = ref<Material | null>(null), materialForm = reactive({ title: '', text: '', tags: '', notes: '', rewrite: '' })
const topics = ref<Topic[]>([]), topic = ref<Topic | null>(null), selectedMembers = ref<string[]>([]), topicEditVisible = ref(false), creatingTopic = ref(false), topicForm = reactive({ name: '', goal: '', description: '' })
const generation = reactive({ action: 'outline', settings: { purpose: '', audience: '', tone: '', length: '' }, request_limit: '' as number | string })
const actionLabels: Record<string, string> = { points: '整理素材要点', structure: '提炼表达结构', angles: '写作角度', outline: '生成提纲', draft: '生成初稿' }
const versionLabels: Record<string, string> = { queued: '等待生成', running: '生成中', completed: '已完成', paused: '额度已用完 · 已暂停', failed: '生成失败', interrupted: '服务中断 · 待核对' }
const previewVisible = ref(false), preview = ref<any>(null), versionEditVisible = ref(false), editingVersion = ref<TopicVersion | null>(null), versionDraft = ref('')
let pollTimer: ReturnType<typeof setTimeout> | null = null, searchSequence = 0
function remember() { sessionStorage.setItem(stateKey, JSON.stringify({ ...query, searched: searched.value, resultsCollapsed: resultsCollapsed.value, resultScroll: resultsViewport.value?.scrollTop || 0, tab: tab.value, scroll: window.scrollY, topic_id: topic.value?.id })) }
function toggleResults() { resultsCollapsed.value = !resultsCollapsed.value; remember() }
function clearSearch() { searchSequence++; busy.value = false; searched.value = false; error.value = ''; resultsCollapsed.value = false; searchResults.value = []; searchTotal.value = 0; Object.assign(query, { q: '', author: '', type: '', sort: 'relevance', page: 1, from: '', to: '' }); remember() }
async function returnToTasks() { resultsCollapsed.value = true; await nextTick(); document.getElementById('task-desk')?.scrollIntoView({ block: 'start' }); remember() }
function changeTab(value: string) { tab.value = value; remember(); if (value === 'materials') void loadMaterials(); if (value === 'topics') void loadTopics() }
async function search(reset: boolean) {
  if (reset) query.page = 1
  resultsCollapsed.value = false
  remember(); const sequence = ++searchSequence; busy.value = true; error.value = ''; searched.value = true
  try { const result = await contentApi.search({ q: query.q, author: query.author, types: query.type === 'distill' ? '' : query.type, scope: query.type === 'distill' ? 'distill' : 'videos', sort: query.sort, page: query.page, page_size: 20, collected_from: query.from, collected_to: query.to }); if (sequence !== searchSequence) return; searchResults.value = result.items; searchTotal.value = result.total; if (result.authors) searchAuthors.value = result.authors; await nextTick(); if (resultsViewport.value) resultsViewport.value.scrollTop = 0 }
  catch (e: any) { if (sequence === searchSequence) error.value = e.message }
  finally { if (sequence === searchSequence) busy.value = false }
}
function snippet(source: ContentSource) { const span = source.spans?.[0]; const start = span ? Math.max(0, span[0] - 60) : 0; const end = Math.min(source.text.length, span ? span[1] + 120 : 180); const text = `${start ? '…' : ''}${source.text.slice(start, end)}${end < source.text.length ? '…' : ''}`; const shift = start ? 1 : 0; return textParts(text, (source.spans || []).map(s => [s[0] - start + shift, s[1] - start + shift])) }
function readMatch(result: ContentVideo, match: ContentSource) { remember(); openContentReader({ aweme_id: result.aweme_id || undefined, source_id: match.source_id, revision: match.revision, spans: match.spans }) }
function dateText(value?: string) { if (!value) return '时间未知'; const date = new Date(value); return Number.isNaN(date.valueOf()) ? value : date.toLocaleString('zh-CN', { month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' }) }
async function loadMaterials() { busy.value = true; try { const result = await contentApi.materials(materialQuery); materials.value = result.items; materialAuthors.value = result.authors || []; materialTags.value = result.tags || [] } catch (e: any) { ElMessage.error(e.message) } finally { busy.value = false } }
function newNote() { editingMaterial.value = null; Object.assign(materialForm, { title: '', text: '', tags: '', notes: '', rewrite: '' }); materialEditVisible.value = true }
function editMaterial(material: Material) { editingMaterial.value = material; Object.assign(materialForm, { title: material.title, text: '', tags: (material.tags || []).join(', '), notes: material.notes || '', rewrite: material.rewrite || '' }); materialEditVisible.value = true }
async function saveMaterial() { if (!materialForm.title.trim() || (!editingMaterial.value && !materialForm.text.trim())) { ElMessage.warning('请填写标题和笔记内容'); return }; busy.value = true; const value = { title: materialForm.title, tags: materialForm.tags.split(/[,，]/).map(s => s.trim()).filter(Boolean), notes: materialForm.notes, rewrite: materialForm.rewrite }; try { if (editingMaterial.value) await contentApi.updateMaterial(editingMaterial.value.id, value); else await contentApi.createMaterial({ ...value, text: materialForm.text, source_type: 'note', request_id: crypto.randomUUID() }); materialEditVisible.value = false; await loadMaterials() } catch (e: any) { ElMessage.error(e.message) } finally { busy.value = false } }
async function removeMaterial(material: Material) { try { await ElMessageBox.confirm('仅删除这条个人素材，不删除视频或来源文本。专题已保存的资料快照将保留。', '删除素材', { type: 'warning' }); await contentApi.deleteMaterial(material.id); await loadMaterials() } catch (e: any) { if (e?.message) ElMessage.error(e.message) } }
async function loadTopics() { try { topics.value = (await contentApi.topics()).items; if (topic.value) await selectTopic(topic.value.id, true); else if (initial.topic_id && topics.value.some(t => t.id === initial.topic_id)) await selectTopic(initial.topic_id) } catch (e: any) { ElMessage.error(e.message) } }
async function selectTopic(id: string, keepSelection = false) { try { const current = await contentApi.topic(id); topic.value = current; if (!keepSelection) { selectedMembers.value = []; Object.assign(generation.settings, { purpose: current.goal || '', audience: '', tone: '', length: '', ...current.settings }) }; remember(); schedulePoll() } catch (e: any) { ElMessage.error(e.message) } }
function createTopic() { creatingTopic.value = true; Object.assign(topicForm, { name: '', goal: '', description: '' }); topicEditVisible.value = true }
function editTopic() { if (!topic.value) return; creatingTopic.value = false; Object.assign(topicForm, topic.value); topicEditVisible.value = true }
async function saveTopic() { if (!topicForm.name.trim()) return; busy.value = true; try { const saved = creatingTopic.value ? await contentApi.createTopic(topicForm) : await contentApi.updateTopic(topic.value!.id, topicForm); topicEditVisible.value = false; topics.value = (await contentApi.topics()).items; await selectTopic(saved.id) } catch (e: any) { ElMessage.error(e.message) } finally { busy.value = false } }
async function deleteTopic() { if (!topic.value) return; try { await ElMessageBox.confirm('删除此专题及其生成版本，不影响来源视频和句子素材。', '删除专题', { type: 'warning' }); await contentApi.deleteTopic(topic.value.id); topic.value = null; await loadTopics() } catch (e: any) { if (e?.message) ElMessage.error(e.message) } }
function selectAllMembers() { selectedMembers.value = selectedMembers.value.length === (topic.value?.members?.length || 0) ? [] : (topic.value?.members || []).map(m => m.id) }
async function addTopicNote() { if (!topic.value) return; try { const result = await ElMessageBox.prompt('这段笔记会作为明确标注的个人资料加入专题。', '添加个人笔记', { inputType: 'textarea', inputValidator: value => !!value?.trim() || '请输入笔记' }); if (typeof result === 'string') return; await contentApi.addMember(topic.value.id, { text: result.value, title: '个人笔记', source_type: 'note' }); await selectTopic(topic.value.id, true) } catch (e: any) { if (e?.message) ElMessage.error(e.message) } }
async function editMember(member: TopicMember) { if (!topic.value) return; try { const group = await ElMessageBox.prompt('填写分组名称，留空表示未分组。', '资料分组', { inputValue: member.group_name || '' }); if (typeof group === 'string') return; const notes = await ElMessageBox.prompt('仅作用于当前专题，不修改原素材。', '专题备注', { inputValue: member.notes || '', inputType: 'textarea' }); if (typeof notes === 'string') return; await contentApi.updateMember(topic.value.id, member.id, { group_name: group.value || '', notes: notes.value || '' }); await selectTopic(topic.value.id, true) } catch (e: any) { if (e?.message) ElMessage.error(e.message) } }
async function moveMember(index: number, step: number) { if (!topic.value?.members) return; const members = topic.value.members.slice(); [members[index], members[index + step]] = [members[index + step], members[index]]; try { for (let i = 0; i < members.length; i++) await contentApi.updateMember(topic.value.id, members[i].id, { position: i }); await selectTopic(topic.value.id, true) } catch (e: any) { ElMessage.error(e.message) } }
async function removeMember(member: TopicMember) { if (!topic.value) return; try { await contentApi.removeMember(topic.value.id, member.id); selectedMembers.value = selectedMembers.value.filter(id => id !== member.id); await selectTopic(topic.value.id, true) } catch (e: any) { ElMessage.error(e.message) } }
function generationPayload() { return { member_ids: [...selectedMembers.value], action: generation.action, settings: { ...generation.settings }, request_limit: generation.request_limit === '' ? null : Number(generation.request_limit) } }
async function previewGeneration() { if (!topic.value) return; busy.value = true; try { preview.value = await contentApi.preview(topic.value.id, generationPayload()); previewVisible.value = true } catch (e: any) { ElMessage.error(e.message) } finally { busy.value = false } }
async function generate() {
  if (!topic.value) return
  const topicId = topic.value.id; busy.value = true; previewVisible.value = false
  const request = contentApi.generate(topicId, generationPayload())
  const refreshTimer = setTimeout(() => { if (topic.value?.id === topicId) void selectTopic(topicId, true) }, 1200)
  try { const version = await request; if (topic.value?.id === topicId) await selectTopic(topicId, true); ElMessage.success(version.status === 'completed' ? '结果已作为独立版本保存' : '任务状态已保存，可在生成版本中查看') }
  catch (e: any) { ElMessage.error(e.message); if (topic.value?.id === topicId) await selectTopic(topicId, true) }
  finally { clearTimeout(refreshTimer); busy.value = false }
}
function editVersion(version: TopicVersion) { editingVersion.value = version; versionDraft.value = version.edited_markdown || version.output_markdown; versionEditVisible.value = true }
async function resumeTopic() {
  if (!topic.value) return
  try {
    const response = await ElMessageBox.prompt('填写本专题累计请求上限（包含之前已用次数），留空不设上限。恢复沿用此版本的原始输入，已完成结果与检查点会保留。', '调整额度并继续', { inputPlaceholder: '新的累计请求上限', inputValidator: value => !value?.trim() || /^[1-9]\d*$/.test(value.trim()) || '请输入正整数或留空' })
    if (typeof response === 'string') return
    const topicId = topic.value.id; busy.value = true
    await contentApi.topicLimit(topicId, response.value?.trim() ? Number(response.value) : null)
    const request = contentApi.resumeTopic(topicId)
    const refreshTimer = setTimeout(() => { if (topic.value?.id === topicId) void selectTopic(topicId, true) }, 1200)
    try { await request; if (topic.value?.id === topicId) await selectTopic(topicId, true); ElMessage.success('已恢复同一生成版本') } finally { clearTimeout(refreshTimer) }
  } catch (e: any) { if (e?.message) ElMessage.error(e.message) } finally { busy.value = false }
}
async function saveVersion() { if (!topic.value || !editingVersion.value) return; busy.value = true; try { await contentApi.editVersion(topic.value.id, editingVersion.value.id, versionDraft.value); versionEditVisible.value = false; await selectTopic(topic.value.id, true) } catch (e: any) { ElMessage.error(e.message) } finally { busy.value = false } }
function exportTopic(versionId?: string) { if (topic.value) window.open(contentApi.exportUrl(topic.value.id, versionId), '_blank', 'noopener') }
function schedulePoll() { if (pollTimer) clearTimeout(pollTimer); if (topic.value?.versions?.some(v => ['queued', 'running'].includes(v.status))) pollTimer = setTimeout(() => { if (topic.value) void selectTopic(topic.value.id, true) }, 2000) }
function refreshContent() { if (tab.value === 'materials') void loadMaterials(); if (tab.value === 'topics') void loadTopics() }
onMounted(async () => { window.addEventListener('content-changed', refreshContent); window.addEventListener('beforeunload', remember); if (tab.value === 'materials') await loadMaterials(); if (tab.value === 'topics') await loadTopics(); if (initial.searched || query.q || query.author || query.type || query.from || query.to) { await search(false); resultsCollapsed.value = Boolean(initial.resultsCollapsed); await nextTick(); if (resultsViewport.value) resultsViewport.value.scrollTop = initial.resultScroll || 0; if (initial.scroll) window.scrollTo({ top: initial.scroll }) } })
onBeforeUnmount(() => { remember(); searchSequence++; window.removeEventListener('content-changed', refreshContent); window.removeEventListener('beforeunload', remember); if (pollTimer) clearTimeout(pollTimer) })
</script>

