gin-top:5px;accent-color:var(--color-accent)}.topic-member h5{font-size:14px;margin:5px 0 8px}.topic-member p{white-space:pre-wrap;line-height:1.8;font-size:12px;max-height:180px;overflow:auto;margin:0 0 10px}.member-note{color:var(--color-text-muted)}.member-actions{display:flex;flex-wrap:wrap;gap:6px}.member-actions .el-button{margin:0;min-height:32px}.topic-generation{padding:22px;background:var(--color-surface);border:1px solid var(--color-line);margin:24px 0}.topic-generation h4{margin:0 0 8px;font-size:16px}.generation-settings{display:grid;grid-template-columns:repeat(2,1fr);gap:14px;margin:18px 0}.generation-settings label,.workspace-field{display:grid;gap:6px;font-size:12px}.generation-settings input,.generation-settings select,.workspace-field input,.workspace-field textarea,.version-editor{padding:10px;border:1px solid var(--color-line-strong);color:var(--color-ink);background:var(--color-paper);font:inherit;min-width:0}.workspace-field{margin:14px 0}.topic-version{padding:20px 0;border-top:1px solid var(--color-line)}.topic-version header{display:flex;justify-content:space-between;gap:20px;font-size:12px}.topic-version header span{color:var(--color-text-muted)}.topic-version pre,.preview-inputs pre{white-space:pre-wrap;font:13px/1.9 var(--font-body);overflow-wrap:anywhere}.topic-version details{font-size:12px;color:var(--color-text-muted)}.topic-version details summary{cursor:pointer}.topic-version footer{margin-top:14px}.version-input,.preview-inputs article{border:1px solid var(--color-line);padding:14px;margin:12px 0}.version-input small,.preview-inputs small{display:block;margin-top:5px;color:var(--color-text-muted)}.version-input p{white-space:pre-wrap;font-size:12px;line-height:1.8}.preview-inputs{max-height:52vh;overflow:auto}.version-editor{width:100%;font:13px/1.8 var(--font-mono)}.el-pagination{margin-top:25px}
